#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>

/* maximum n that the original program accepted */
#define MAX_N 30

/* compute Catalan numbers up to MAX_N using the classic DP recurrence */
static long long catalan(int n)
{
    long long cat[MAX_N + 1] = {0};
    cat[0] = 1;
    for (int i = 1; i <= n; ++i) {
        long long sum = 0;
        for (int j = 0; j < i; ++j) {
            sum += cat[j] * cat[i - 1 - j];
        }
        cat[i] = sum;
    }
    return cat[n];
}

int main(int argc, char *argv[])
{
    /* ----- no argument --------------------------------------------------- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* ----- parse the argument ------------------------------------------- */
    char *endptr;
    errno = 0;
    long val = strtol(argv[1], &endptr, 10);

    /* parsing failed (no digits) or extra characters after the number */
    if (endptr == argv[1] || *endptr != '\0' || errno != 0) {
        puts("BAD_INPUT");
        return 0;
    }

    /* ----- range checks ------------------------------------------------- */
    if (val < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (val > MAX_N) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ----- compute and print the Catalan number ------------------------ */
    long long result = catalan((int)val);
    printf("%lld\n", result);
    return 0;
}
